const esc=(value)=>String(value??"").replace(/[&<>"']/g,(c)=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const reportPhrase=(item)=>item.report_generated_on?`${item.report_window_days} дней · отчёт сформирован ${new Date(`${item.report_generated_on}T00:00:00`).toLocaleDateString("ru-RU")}`:"Период не определён";
const historyContext=(item)=>{if(item.report_type==="OZON_PRODUCTS")return ["Товары на Ozon",reportPhrase(item)];if(item.report_type==="OZON_SEARCH_VISIBILITY")return ["Поисковая видимость Ozon",`${item.query_text} · ${item.cluster_name} · ${item.observed_at} · заявлено ${item.declared_rows}, принято ${item.rows_accepted}, пропущено ${item.rows_skipped}`];if(item.report_type==="OZON_OWN_PRODUCT_QUERIES")return ["Запросы моего товара",`Ozon ID ${item.report_product_ozon_id} · ${item.period_start} — ${item.period_end} · принято ${item.rows_accepted}, пропущено ${item.rows_skipped}`];if(item.report_type==="OZON_QUERY_METRICS")return ["Метрики поисковых запросов",`${item.period_start} — ${item.period_end} · ${item.sort_context} · принято ${item.rows_accepted}, пропущено ${item.rows_skipped}`];return ["Неизвестный тип отчёта","Контекст не определён"];};
let focusAfterRouteChange=false;
function navigateTo(route,{replace=false,state=null,focus=true}={}){focusAfterRouteChange=focus;const url=ScozProductNavigation.serializeRoute(route);const value={...(state||{}),scozNavIndex:history.state?.scozNavIndex??0};if(replace)history.replaceState(value,"",url);else history.pushState({...value,scozNavIndex:value.scozNavIndex+1},"",url);renderedNavIndex=history.state.scozNavIndex;renderCurrentRoute();}
function showGlobalRoute(section){document.querySelector(".page-header").hidden=false;document.querySelectorAll(".nav-item").forEach((item)=>{const active=item.dataset.section===section;item.classList.toggle("is-active",active);if(active)item.setAttribute("aria-current","page");else item.removeAttribute("aria-current");});document.querySelectorAll(".view").forEach((view)=>view.hidden=view.id!==`${section}-view`);const values=copy[section];[document.querySelector("#page-title").textContent,document.querySelector("#page-description").textContent]=values;document.title=ScozProductNavigation.documentTitle({kind:section});if(focusAfterRouteChange){document.querySelector("#page-title").focus();focusAfterRouteChange=false;}}
function renderCurrentRoute(){const route=ScozProductNavigation.parseHash(location.hash);if(route.kind==="products"){showGlobalRoute("products");document.querySelector("#catalog-search").value=route.query;document.querySelector("#catalog-search-clear").hidden=!route.query;loadOwnedProducts().catch(()=>{});loadCatalog(route);return;}if(route.kind==="workspace"){document.querySelector(".page-header").hidden=true;document.querySelectorAll(".view").forEach((view)=>view.hidden=view.id!=="product-workspace");document.querySelectorAll(".nav-item").forEach((item)=>{item.classList.toggle("is-active",item.dataset.section==="products");if(item.dataset.section==="products")item.setAttribute("aria-current","page");else item.removeAttribute("aria-current");});document.querySelector("#product-workspace").setAttribute("aria-busy","true");loadWorkspaceContext(route.productId);return;}if(route.kind==="data"||route.kind==="settings"){showGlobalRoute(route.kind);return;}navigateTo({kind:"products",query:"",page:1},{replace:true});document.querySelector("#products-status").hidden=false;document.querySelector("#products-status").textContent="Маршрут не найден. Выберите раздел приложения.";}
