async function loadImports(){const target=document.querySelector("#import-history");target.textContent="Загрузка…";try{const data=await(await fetch("/api/imports")).json();document.querySelector("#seller-queries-readiness").textContent=data.source_availability.own_product_queries?"Источник загружен":"Источник не загружен";document.querySelector("#query-metrics-readiness").textContent=data.source_availability.query_metrics?"Источник загружен":"Источник не загружен";target.innerHTML=data.items.length?data.items.map((item)=>{const [label,context]=historyContext(item);return `<div class="history-item"><strong>${esc(item.status)} · ${esc(label)}</strong><span>${esc(context)}</span><span>Импортирован: ${esc(item.finished_at||item.started_at)}</span><span>${esc(item.source_artifact?.original_name)} · принято ${item.rows_accepted}, пропущено ${item.rows_skipped}, дубликатов ${item.duplicate_observations}, новых ${item.new_observations}, исправлений ${item.corrected_revisions}, предупреждений ${item.warnings_count}, ошибок ${item.row_errors_total}</span></div>`;}).join(""):"История пуста";}catch{target.textContent="Не удалось загрузить историю";}}
function productFreshness(item){return item.product_data_status==="AVAILABLE"&&item.report_generated_on?`${new Date(`${item.report_generated_on}T00:00:00`).toLocaleDateString("ru-RU")} · ${item.report_window_days} дней`:"Товар определён · нужны товарные данные";}
function renderOwnedProducts(items){const target=document.querySelector("#owned-products-list");target.innerHTML=items.map((item)=>`<article class="owned-product"><div><strong>${esc(item.title||`Товар Ozon ${item.ozon_product_id}`)}</strong><span>Ozon ID: ${esc(item.ozon_product_id)}</span><span>${esc(productFreshness(item))}</span></div><div class="button-row"><button type="button" class="button button-primary button-compact" data-open-product="${item.product_id}">Открыть</button><button type="button" class="button button-secondary button-compact" data-remove-owned="${item.product_id}">Убрать из моих товаров</button></div></article>`).join("");target.querySelectorAll("[data-open-product]").forEach((button)=>button.addEventListener("click",()=>openProductWorkspace(Number(button.dataset.openProduct),button)));target.querySelectorAll("[data-remove-owned]").forEach((button)=>button.addEventListener("click",()=>setOwnership(Number(button.dataset.removeOwned),false,button)));}
async function loadOwnedProducts({reportError=true}={}){const status=document.querySelector("#owned-products-status");productUiState.ownedProductsState="loading";setStatusState(status,"neutral");status.textContent="Загрузка…";try{const data=await responseBody(await fetch("/api/products/owned"));productUiState.ownedProducts=data.items;productUiState.ownedProductsState="loaded";renderOwnedProducts(data.items);status.textContent=data.items.length?`Моих товаров: ${data.total}`:"Добавьте свой товар из каталога Ozon.";return data;}catch(error){productUiState.ownedProductsState="error";if(reportError)status.textContent=`Не удалось загрузить мои товары. ${error.message}`;throw error;}}
function renderCatalog(data,route){const body=document.querySelector("#catalog-table-body"),status=document.querySelector("#catalog-status");productUiState.catalogItems=data.items;productUiState.catalogTotal=data.total;body.innerHTML=data.items.map((item)=>`<tr><td><strong>${esc(item.title||`Товар Ozon ${item.ozon_product_id}`)}</strong>${item.seller_name||item.brand?`<br><small>${esc([item.seller_name,item.brand].filter(Boolean).join(" · "))}</small>`:""}</td><td>${esc(item.ozon_product_id)}</td><td>${esc(productFreshness(item))}</td><td>${item.is_owned?"Мой товар":"—"}</td><td><div class="ownership-action"><button type="button" class="button button-primary button-compact" data-catalog-ownership="${item.product_id}" data-owned="${item.is_owned}">${item.is_owned?`Открыть</button> <button type="button" class="button button-secondary button-compact" data-catalog-ownership="${item.product_id}" data-owned="true">Убрать из моих товаров`:"Добавить в мои товары"}</button><span class="ownership-feedback" data-ownership-feedback="${item.product_id}" aria-live="polite"></span></div></td></tr>`).join("");body.querySelectorAll("[data-catalog-ownership]").forEach((button)=>button.addEventListener("click",()=>{if(button.dataset.owned==="true"&&button.textContent==="Открыть")openProductWorkspace(Number(button.dataset.catalogOwnership),button);else setOwnership(Number(button.dataset.catalogOwnership),button.dataset.owned!=="true",button);}));const start=data.total?data.offset+1:0,end=Math.min(data.offset+data.limit,data.total);document.querySelector("#catalog-range").textContent=`${start}${start&&end!==start?`–${end}`:""} из ${data.total}`;document.querySelector("#catalog-prev").disabled=route.page===1;document.querySelector("#catalog-next").disabled=end>=data.total;status.textContent=data.total?"":route.query?`По запросу «${route.query}» ничего не найдено.`:"Каталог пуст. Импортируйте отчёт «Товары на Ozon» в разделе «Данные».";if(!data.total&&route.query){status.innerHTML+=` <button type="button" class="button button-ghost button-compact" data-reset-search>Сбросить поиск</button>`;status.querySelector("[data-reset-search]").addEventListener("click",()=>navigateTo({kind:"products",query:"",page:1},{replace:true}));}}
async function loadCatalog(route){const requestId=++productUiState.catalogRequestId,status=document.querySelector("#catalog-status");status.textContent="Загрузка каталога…";try{const params=new URLSearchParams({limit:String(CATALOG_PAGE_SIZE),offset:String((route.page-1)*CATALOG_PAGE_SIZE)});if(route.query)params.set("q",route.query);const data=await responseBody(await fetch(`/api/products?${params}`));const current=ScozProductNavigation.parseHash(location.hash);if(requestId!==productUiState.catalogRequestId||current.kind!=="products"||current.query!==route.query||current.page!==route.page)return;const lastPage=Math.max(1,Math.ceil(data.total/CATALOG_PAGE_SIZE));if(route.page>lastPage){navigateTo({kind:"products",query:route.query,page:lastPage},{replace:true});return;}renderCatalog(data,route);requestAnimationFrame(()=>window.scrollTo(0,history.state?.catalogScrollY||0));}catch(error){if(requestId===productUiState.catalogRequestId)status.textContent=`Не удалось загрузить каталог. ${error.message}`;}}
async function setOwnership(productId,isOwned,button){if(button.dataset.pending==="true")return;const originalText=button.textContent,fromOwnedList=Boolean(button.closest("#owned-products-list")),localFeedback=document.querySelector(`[data-ownership-feedback="${productId}"]`),status=localFeedback||(fromOwnedList?document.querySelector("#owned-products-status"):document.querySelector("#catalog-status"));button.dataset.pending="true";button.disabled=true;button.textContent="Сохраняем…";status.textContent="";try{await responseBody(await fetch(`/api/products/${productId}/ownership`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({is_owned:isOwned})}));const route=ScozProductNavigation.parseHash(location.hash);await Promise.all([loadOwnedProducts().catch(()=>{}),route.kind==="products"?loadCatalog(route):Promise.resolve()]);const refreshed=document.querySelector(`[data-ownership-feedback="${productId}"]`);if(refreshed)refreshed.textContent=isOwned?"Добавлено в «Мои товары».":"Товар убран из «Моих товаров».";if(fromOwnedList&&!isOwned){status.textContent=productUiState.ownedProducts.length===0?"Товар убран из «Моих товаров». Добавьте свой товар из каталога Ozon.":"Товар убран из «Моих товаров».";setStatusState(status,"success");}}catch(error){button.textContent=originalText;status.innerHTML=`Не удалось изменить принадлежность товара. ${esc(error.message)} <button type="button" class="button button-secondary button-compact" data-ownership-retry>Повторить</button>`;status.querySelector("[data-ownership-retry]").addEventListener("click",()=>setOwnership(productId,isOwned,button));}finally{button.dataset.pending="false";button.disabled=false;}}
function openProductWorkspace(productId,source){history.replaceState({...history.state,catalogScrollY:window.scrollY},"",location.href);requestNavigation({kind:"workspace",productId,section:"competitors"},source);}
async function loadProducts(){const route=ScozProductNavigation.parseHash(location.hash);if(route.kind==="products")await Promise.all([loadOwnedProducts().catch(()=>{}),loadCatalog(route)]);}

function isCurrentWorkspaceRequest(requestId,productId){const route=ScozProductNavigation.parseHash(location.hash);return requestId===productUiState.workspaceRequestId&&route.kind==="workspace"&&route.productId===productId&&route.section==="competitors";}
function renderProductContextHeader(context){const product=context.product,title=product.title||`Товар Ozon ${product.ozon_product_id}`;document.querySelector("#workspace-title").textContent=title;document.querySelector("#workspace-product-id").textContent=`Ozon ID: ${product.ozon_product_id}`;const values=[product.seller_name,product.brand];if(product.product_data_status==="AVAILABLE")values.push(productFreshness(product));document.querySelector("#workspace-product-meta").textContent=values.filter(Boolean).join(" · ");document.title=ScozProductNavigation.documentTitle({kind:"workspace",productId:product.product_id,section:"competitors"},title);}
function renderEvidenceRail(context){const product=context.product,queries=context.queries,benchmark=context.benchmark;document.querySelector("#workspace-evidence-product").textContent=product.product_data_status==="AVAILABLE"?`Товарные данные · ${productFreshness(product)}`:"Товарные данные · нужны данные";document.querySelector("#workspace-evidence-search").textContent=queries.readiness==="READY"?`Поиск · выбрано ${queries.selected_count} запросов`:queries.readiness==="EMPTY_SELECTION"?"Поиск · запросы не выбраны":"Поиск · нужны данные запросов";document.querySelector("#workspace-evidence-benchmark").textContent=benchmark.status==="CONFIGURED"?`Группа сравнения · ${benchmark.member_count} товаров`:"Группа сравнения · не настроена";}
async function loadWorkspaceContext(productId){const requestId=++productUiState.workspaceRequestId,status=document.querySelector("#product-workspace-status"),previousContext=competitorState.activeProduct?{product:{...competitorState.activeProduct,product_id:competitorState.activeProduct.id},title:document.querySelector("#workspace-title").textContent}:null;document.title="Загрузка… — SCOZ";status.textContent="Загрузка рабочего пространства…";try{const response=await fetch(`/api/products/${productId}/workspace-context`);const body=await response.json();if(!isCurrentWorkspaceRequest(requestId,productId))return;if(!response.ok)throw new Error(response.status===404?"Товар не найден.":response.status===409?"Товар больше не входит в «Мои товары».":body.error?.message||"Не удалось загрузить товар.");renderProductContextHeader(body);renderEvidenceRail(body);status.textContent="";resetCompetitorState({...body.product,id:body.product.product_id});await Promise.all([loadRelevantQueries(productId,requestId),loadBenchmark(productId,requestId)]);if(isCurrentWorkspaceRequest(requestId,productId)&&competitorState.relevance?.selected_count)await loadCandidates(productId,0,requestId);if(isCurrentWorkspaceRequest(requestId,productId)){document.querySelector("#product-workspace").setAttribute("aria-busy","false");document.querySelector("#workspace-title").focus();}}catch(error){if(!isCurrentWorkspaceRequest(requestId,productId))return;if(previousContext&&previousContext.product.id!==productId){history.replaceState(history.state,"",ScozProductNavigation.serializeRoute({kind:"workspace",productId:previousContext.product.id,section:"competitors"}));document.title=ScozProductNavigation.documentTitle({kind:"workspace",productId:previousContext.product.id,section:"competitors"},previousContext.title);status.textContent=`Не удалось сменить товар. ${error.message}`;document.querySelector("#product-workspace").setAttribute("aria-busy","false");document.querySelector("#product-switcher-trigger").focus();return;}document.title="Ошибка загрузки товара — SCOZ";status.innerHTML=`${esc(error.message)} <button type="button" class="button button-secondary button-compact" data-workspace-retry>Повторить</button> <button type="button" class="button button-ghost button-compact" data-products-return>Вернуться к товарам</button>`;status.querySelector("[data-workspace-retry]").addEventListener("click",()=>loadWorkspaceContext(productId));status.querySelector("[data-products-return]").addEventListener("click",()=>requestNavigation({kind:"products",query:"",page:1},status.querySelector("[data-products-return]")));document.querySelector("#product-workspace").setAttribute("aria-busy","false");}}
function filterOwnedProductsForSwitcher(input){const needle=input.normalize("NFKC").toLocaleLowerCase("ru-RU");return productUiState.ownedProducts.filter((item)=>{const title=(item.title||"").normalize("NFKC").toLocaleLowerCase("ru-RU");return title.includes(needle)||(/^\d+$/.test(needle)&&item.ozon_product_id.startsWith(needle));});}
let switcherItems=[],switcherActive=-1;
function renderSwitcherOptions(){const target=document.querySelector("#product-switcher-listbox"),query=document.querySelector("#product-switcher-search").value;switcherItems=filterOwnedProductsForSwitcher(query);switcherActive=Math.min(switcherActive,switcherItems.length-1);const currentId=competitorState.activeProduct?.id;target.innerHTML=switcherItems.map((item,index)=>`<div id="product-switcher-option-${item.product_id}" role="option" aria-selected="${item.product_id===currentId}" aria-current="${item.product_id===currentId}" data-switch-product="${item.product_id}" class="${index===switcherActive?"is-keyboard-active":""}">${esc(item.title||`Товар Ozon ${item.ozon_product_id}`)} · ${esc(item.ozon_product_id)}${item.product_id===currentId?'<span class="current-product-marker">Открыт</span>':""}</div>`).join("");document.querySelector("#product-switcher-status").textContent=switcherItems.length?`${switcherItems.length} товаров`:query?"Ничего не найдено":"Нет своих товаров";const input=document.querySelector("#product-switcher-search");if(switcherActive>=0)input.setAttribute("aria-activedescendant",`product-switcher-option-${switcherItems[switcherActive].product_id}`);else input.removeAttribute("aria-activedescendant");target.querySelectorAll("[data-switch-product]").forEach((option)=>option.addEventListener("click",()=>selectSwitcherProduct(Number(option.dataset.switchProduct))));}
function renderSwitcherLoadError(error){const status=document.querySelector("#product-switcher-status"),target=document.querySelector("#product-switcher-listbox");target.replaceChildren();status.innerHTML=`Не удалось загрузить список товаров. ${esc(error.message)} <button type="button" class="button button-secondary button-compact" data-switcher-retry>Повторить</button>`;status.querySelector("[data-switcher-retry]").addEventListener("click",loadSwitcherProducts);}
async function loadSwitcherProducts(){const status=document.querySelector("#product-switcher-status");status.textContent="Загрузка…";try{await loadOwnedProducts({reportError:false});renderSwitcherOptions();}catch(error){renderSwitcherLoadError(error);}}
async function openProductSwitcher(){const popover=document.querySelector("#product-switcher-popover"),trigger=document.querySelector("#product-switcher-trigger");popover.hidden=false;trigger.setAttribute("aria-expanded","true");document.querySelector("#product-switcher-search").value="";switcherActive=-1;if(productUiState.ownedProductsState!=="loaded")await loadSwitcherProducts();else renderSwitcherOptions();document.querySelector("#product-switcher-search").focus();}
function closeProductSwitcher({restoreFocus=true}={}){document.querySelector("#product-switcher-popover").hidden=true;document.querySelector("#product-switcher-trigger").setAttribute("aria-expanded","false");if(restoreFocus)document.querySelector("#product-switcher-trigger").focus();}
function selectSwitcherProduct(productId){if(productId===competitorState.activeProduct?.id){closeProductSwitcher();return;}closeProductSwitcher({restoreFocus:false});requestNavigation({kind:"workspace",productId,section:"competitors"},document.querySelector("#product-switcher-search"));}
function normalizedIds(values){return [...values].map(Number).sort((a,b)=>a-b);}
function hasUnsavedCompetitorChanges(){const persistedQueries=normalizedIds((competitorState.relevance?.items||[]).filter((item)=>item.selected).map((item)=>item.search_query_id)),currentQueries=normalizedIds([...document.querySelectorAll("[data-query-id]:checked")].map((item)=>item.dataset.queryId));const persistedMembers=normalizedIds((competitorState.benchmark?.current_revision?.members||[]).map((item)=>item.product_id)),currentMembers=normalizedIds(competitorState.selectedProductIds);return JSON.stringify(persistedQueries)!==JSON.stringify(currentQueries)||JSON.stringify(persistedMembers)!==JSON.stringify(currentMembers);}
let pendingNavigation=null,pendingNavigationFocus=null;
function requestNavigation(route,source){const current=ScozProductNavigation.parseHash(location.hash);if(current.kind==="workspace"&&hasUnsavedCompetitorChanges()){pendingNavigation=route;pendingNavigationFocus=source;document.querySelector("#unsaved-changes-dialog").showModal();return;}navigateTo(route);}
function setStatusState(status,state){status.classList.remove("is-working","is-success","is-warning","is-error");if(state!=="neutral")status.classList.add(`is-${state}`);}
function renderWorkingImport(token){const seconds=Math.floor((Date.now()-token.startedAt)/1000);token.status.textContent=`${ScozImportUi.workingMessage(seconds)}\nФайл обрабатывается локально. Не закрывайте приложение.`;}
function restoreImportControls(){Object.values(importSources).forEach((source)=>{const input=document.querySelector(source.input),button=document.querySelector(source.button);input.disabled=false;button.disabled=!input.files[0];button.textContent="Импортировать";});}
function beginImportUi(sourceKey){if(activeImport)return null;const source=importSources[sourceKey],status=document.querySelector(source.status),card=status.closest(".import-card");activeImport={sourceKey,startedAt:Date.now(),status,card,timer:null};Object.values(importSources).forEach((item)=>{document.querySelector(item.input).disabled=true;document.querySelector(item.button).disabled=true;});document.querySelector(source.button).textContent="Импортируем…";card.setAttribute("aria-busy","true");document.querySelector("#data-view").setAttribute("aria-busy","true");setStatusState(status,"working");renderWorkingImport(activeImport);activeImport.timer=setInterval(()=>renderWorkingImport(activeImport),250);return activeImport;}
function finishImportUi(token,state,message){if(!token||activeImport!==token)return;clearInterval(token.timer);const elapsed=ScozImportUi.formatElapsed((Date.now()-token.startedAt)/1000);token.status.textContent=`${message} · ${elapsed}`;setStatusState(token.status,state);token.card.setAttribute("aria-busy","false");document.querySelector("#data-view").setAttribute("aria-busy","false");activeImport=null;restoreImportControls();}
async function submitOzonProductsImport(file){const token=beginImportUi("ozon_products");if(!token)return;let outcome={state:"error",message:"Не удалось выполнить импорт"};const form=new FormData();form.append("file",file);try{const response=await fetch("/api/imports/ozon-products",{method:"POST",body:form});const result=await response.json();if(!response.ok){outcome.message=`Ошибка импорта · ${result.error?.message||"Ошибка импорта"}`;}else{if(result.status==="PARTIAL_SUCCESS"){const details=result.row_errors.map((item)=>`Строка ${item.row}: ${item.message}`).join("; ");outcome={state:"warning",message:`Частичный импорт · принято ${result.rows_accepted} из ${result.rows_accepted+result.rows_skipped} · пропущено ${result.rows_skipped}${details?`. ${details}`:""}`};}else{outcome={state:"success",message:`Импорт завершён · принято ${result.rows_accepted}`};}await Promise.all([loadImports(),loadProducts()]);}}catch{outcome={state:"error",message:"Не удалось выполнить импорт"};}finally{finishImportUi(token,outcome.state,outcome.message);}}
async function submitSearchVisibilityImport(file){const token=beginImportUi("search_visibility");if(!token)return;let outcome={state:"error",message:"Не удалось выполнить импорт"};const form=new FormData();form.append("file",file);try{const response=await fetch("/api/imports/ozon-search-visibility",{method:"POST",body:form});const body=await response.json(),result=response.ok?body:body.result;if(!response.ok){const details=result?.row_errors?.map((item)=>`Строка ${item.row}: ${item.message}`).join("; ");outcome.message=`Ошибка импорта · ${body.error?.message||"Ошибка импорта"}${details?`. ${details}`:""}`;}else{const context=`${result.query_text} · ${result.cluster_name} · ${result.observed_at}`;if(result.status==="PARTIAL_SUCCESS"){const details=result.row_errors.map((item)=>`Строка ${item.row}: ${item.message}`).join("; ");outcome={state:"warning",message:`Частичный импорт · ${context} · принято ${result.rows_accepted} из ${result.rows_accepted+result.rows_skipped} · пропущено ${result.rows_skipped}${details?`. ${details}`:""}`};}else outcome={state:"success",message:`Импорт завершён · ${context} · принято ${result.rows_accepted} · новых ${result.new_observations} · дубликатов ${result.duplicate_observations} · исправлений ${result.corrected_revisions}`};await loadImports();}}catch{outcome={state:"error",message:"Не удалось выполнить импорт"};}finally{finishImportUi(token,outcome.state,outcome.message);}}
async function submitSellerQueriesImport(file){await submitQueryImport(file,"seller_queries","/api/imports/ozon-seller-queries",true);}
async function submitQueryMetricsImport(file){await submitQueryImport(file,"query_metrics","/api/imports/ozon-query-metrics",false);}
async function submitQueryImport(file,sourceKey,endpoint,refreshProducts){const token=beginImportUi(sourceKey);if(!token)return;let outcome={state:"error",message:"Не удалось выполнить импорт"};const form=new FormData();form.append("file",file);try{const response=await fetch(endpoint,{method:"POST",body:form});const body=await response.json(),result=response.ok?body:body.result;if(!response.ok){outcome.message=`Ошибка импорта · ${body.error?.message||"Ошибка импорта"}`;if(body.result)await loadImports();}else{const errors=result.row_errors.map((item)=>`Строка ${item.row}: ${item.message}`).join("; ");outcome=result.status==="PARTIAL_SUCCESS"?{state:"warning",message:`Частичный импорт · принято ${result.rows_accepted} из ${result.rows_accepted+result.rows_skipped} · пропущено ${result.rows_skipped}${errors?`. ${errors}`:""}`}:{state:"success",message:`Импорт завершён · принято ${result.rows_accepted}`};await (refreshProducts?Promise.all([loadImports(),loadProducts()]):loadImports());}}catch{outcome={state:"error",message:"Не удалось выполнить импорт"};}finally{finishImportUi(token,outcome.state,outcome.message);}}

function resetCoreBenchmarkState(){competitorState.coreBenchmark=null;competitorState.coreBenchmarkRequestId+=1;const panel=document.querySelector("#core-benchmark-panel");if(panel)panel.hidden=true;}
function resetCompetitorState(product){resetCoreBenchmarkState();competitorState.activeProduct=product;competitorState.relevance=null;competitorState.candidatePage=null;competitorState.benchmark=null;competitorState.selectedProductIds=new Set();competitorState.metadataByProductId=new Map();competitorState.candidateOffset=0;}
function setBenchmarkControls(enabled){document.querySelector("#manual-candidate-add").disabled=!enabled;document.querySelector("#benchmark-save").disabled=!enabled;}
async function responseBody(response){const body=await response.json();if(!response.ok)throw new Error(body.error?.message||"Не удалось выполнить запрос.");return body;}
const coreBenchmarkGroups=[
  ["Результат",["ordered_amount_rub","ordered_units","buyout_share_pct"]],
  ["Трафик",["impressions_total","search_catalog_views","card_views"]],
  ["Конверсия",["impression_to_order_pct","search_catalog_to_cart_pct","card_to_cart_pct"]],
  ["Предложение",["average_price_rub"]],
  ["Реклама",["total_drr_pct","estimated_ad_spend_rub","advertising_support_per_ordered_unit_rub"]],
];
const benchmarkPositionLabel={BELOW_MEDIAN:"Ниже медианы",AT_MEDIAN:"На уровне медианы",ABOVE_MEDIAN:"Выше медианы",UNAVAILABLE:"—"};
function formatBenchmarkValue(value, unit, options={}){if(value===null||value===undefined)return "—";const number=Number(value),isPercentage=unit==="PERCENTAGE_POINTS",formatted=new Intl.NumberFormat("ru-RU",{minimumFractionDigits:isPercentage?1:0,maximumFractionDigits:isPercentage?1:0,signDisplay:options.signed?"always":"auto"}).format(number);if(isPercentage)return `${formatted}${options.delta?" п.п.":"%"}`;if(unit==="RUB")return `${formatted} ₽`;if(unit==="RUB_PER_ORDERED_UNIT")return `${formatted} ₽/заказанную ед.`;return formatted;}
function coreBenchmarkObservationPhrase(observation){if(!observation)return "";const [year,month,day]=observation.report_generated_on.split("-");return `${observation.report_window_days} дней · отчёт сформирован ${day}.${month}.${year}`;}
function benchmarkDetailValue(value,unit,options={}){return value===null||value===undefined?'<span>— <small>Недоступно для текущей выборки</small></span>':esc(formatBenchmarkValue(value,unit,options));}
function renderCoreBenchmarkMetric(metric, benchmark){const detailId=`core-benchmark-detail-${metric.metric_id.replace(/[^a-z0-9_-]/g,"-")}`,exclusions=metric.exclusion_summary||{},samples=metric.sample_values||[];return `<article class="core-benchmark-metric ${metric.direction==="CONTEXTUAL"?"is-contextual":""}"><button type="button" class="button button-ghost core-benchmark-metric-toggle" aria-expanded="false" aria-controls="${detailId}"><span><strong>${esc(metric.label)}</strong>${metric.is_estimate?' <span class="chip">Оценка</span>':""}</span><span>${esc(benchmarkPositionLabel[metric.comparison_position]||"—")}</span></button><dl><div><dt>Свой</dt><dd>${esc(formatBenchmarkValue(metric.own_value,metric.unit))}</dd></div><div><dt>Медиана</dt><dd>${esc(formatBenchmarkValue(metric.median,metric.unit))}</dd></div><div><dt>Δ</dt><dd>${esc(formatBenchmarkValue(metric.absolute_delta,metric.unit,{signed:true,delta:true}))}</dd></div><div><dt>N</dt><dd>${esc(metric.sample_size)}</dd></div><div><dt>Позиция</dt><dd>${esc(benchmarkPositionLabel[metric.comparison_position]||"—")}</dd></div><div><dt>Уверенность</dt><dd>${esc(metric.confidence)}</dd></div></dl><div id="${detailId}" class="core-benchmark-detail" hidden><dl><div><dt>P25</dt><dd>${benchmarkDetailValue(metric.p25,metric.unit)}</dd></div><div><dt>P75</dt><dd>${benchmarkDetailValue(metric.p75,metric.unit)}</dd></div><div><dt>Дельта</dt><dd>${benchmarkDetailValue(metric.absolute_delta,metric.unit,{signed:true,delta:true})}</dd></div></dl><p>${esc(coreBenchmarkObservationPhrase(benchmark.observation))} · ревизия ${esc(benchmark.benchmark?.benchmark_revision_number??"—")} · участников ${esc(benchmark.benchmark?.benchmark_member_count??0)}</p><h4>Участники выборки</h4><ul>${samples.map((item)=>`<li><span>${esc(item.title||`Товар Ozon ${item.ozon_product_id}`)}</span><strong>${esc(formatBenchmarkValue(item.value,metric.unit))}</strong></li>`).join("")||"<li>—</li>"}</ul><h4>Исключения</h4><ul><li>Нет совместимого наблюдения: ${esc(exclusions.NO_COMPATIBLE_OBSERVATION??0)}</li><li>Нет исходного значения показателя: ${esc(exclusions.SOURCE_METRIC_UNAVAILABLE??0)}</li><li>Нельзя вычислить производный показатель: ${esc(exclusions.DERIVED_VALUE_UNAVAILABLE??0)}</li></ul></div></article>`;}
function toggleCoreBenchmarkMetricDetail(button){const detail=document.getElementById(button.getAttribute("aria-controls")),expanded=button.getAttribute("aria-expanded")==="true";button.setAttribute("aria-expanded",String(!expanded));if(detail)detail.hidden=expanded;}
function renderCoreBenchmark(result){const context=document.querySelector("#core-benchmark-context"),target=document.querySelector("#core-benchmark-groups");context.textContent=`${coreBenchmarkObservationPhrase(result.observation)} · ревизия ${result.benchmark?.benchmark_revision_number??"—"} · участников ${result.benchmark?.benchmark_member_count??0}`;const byId=new Map(result.metrics.map((metric)=>[metric.metric_id,metric]));target.innerHTML=coreBenchmarkGroups.map(([group,ids])=>`<section class="core-benchmark-group"><h3>${group}</h3>${ids.map((id)=>{const metric=byId.get(id);return metric?renderCoreBenchmarkMetric(metric,result):"";}).join("")}</section>`).join("");target.querySelectorAll(".core-benchmark-metric-toggle").forEach((button)=>button.addEventListener("click",()=>toggleCoreBenchmarkMetricDetail(button)));}
function renderCoreBenchmarkState(state, result){const status=document.querySelector("#core-benchmark-status"),context=document.querySelector("#core-benchmark-context"),groups=document.querySelector("#core-benchmark-groups"),retry=document.querySelector("#core-benchmark-retry");context.replaceChildren();groups.replaceChildren();retry.hidden=true;const messages={LOADING:"Рассчитываем сравнение…",NO_BENCHMARK:"Сначала сохраните группу сравнения.",NO_OWN_SOURCE_DATA:"Нет товарных данных Ozon для собственного товара. Импортируйте отчёт «Товары на Ozon».",NO_COMPATIBLE_SAMPLE:"У конкурентов нет данных за тот же контекст отчёта.",INSUFFICIENT_SAMPLE:"Совместимых конкурентов недостаточно для сравнения.",READY:"",FAILED:"Не удалось загрузить сравнение. Повторите попытку."};status.textContent=messages[state]??"";if(state==="FAILED"){retry.hidden=false;return;}if(result?.observation&&(state==="READY"||state==="INSUFFICIENT_SAMPLE"||state==="NO_COMPATIBLE_SAMPLE")){renderCoreBenchmark(result);if(state==="READY"&&result.metrics.some((metric)=>metric.readiness!=="READY"))status.textContent="Часть показателей недоступна";}}
async function loadCoreBenchmark(productId, requestId){try{const result=await responseBody(await fetch(`/api/products/${productId}/core-benchmark`));if(requestId!==competitorState.coreBenchmarkRequestId||competitorState.activeProduct?.id!==productId)return;competitorState.coreBenchmark=result;renderCoreBenchmarkState(result.readiness,result);}catch{if(requestId!==competitorState.coreBenchmarkRequestId||competitorState.activeProduct?.id!==productId)return;competitorState.coreBenchmark=null;renderCoreBenchmarkState("FAILED",null);}}
async function openCoreBenchmark(){const panel=document.querySelector("#core-benchmark-panel"),productId=competitorState.activeProduct?.id;if(!panel||!productId)return;panel.hidden=false;const requestId=++competitorState.coreBenchmarkRequestId;competitorState.coreBenchmark=null;renderCoreBenchmarkState("LOADING",null);await loadCoreBenchmark(productId, requestId);}
async function openCompetitorWorkspace(product){
}
async function loadRelevantQueries(productId,requestId=productUiState.workspaceRequestId){const status=document.querySelector("#relevant-queries-status"),button=document.querySelector("#relevant-queries-save");status.textContent="Загрузка запросов…";button.disabled=true;try{const selection=await responseBody(await fetch(`/api/products/${productId}/relevant-queries`));if(!isCurrentWorkspaceRequest(requestId,productId))return null;competitorState.relevance=selection;renderRelevantQueries(selection);return selection;}catch(error){if(!isCurrentWorkspaceRequest(requestId,productId))return null;status.textContent=error.message;return null;}}
function renderRelevantQueries(selection){const status=document.querySelector("#relevant-queries-status"),table=document.querySelector("#relevant-queries-table"),button=document.querySelector("#relevant-queries-save");if(selection.readiness==="NO_OWN_QUERY_DATA"){status.innerHTML='Нет данных по запросам. <button type="button" class="button button-ghost button-compact" data-open-data>Перейти в Данные</button>';table.replaceChildren();button.disabled=true;status.querySelector("[data-open-data]").addEventListener("click",()=>document.querySelector('[data-section="data"]').click());return;}const period=selection.latest_period?`${selection.latest_period.period_start} — ${selection.latest_period.period_end}`:"Период не определён";status.textContent=`Период: ${period}. Выбрано: ${selection.selected_count}. ${selection.selected_count?"":"Выберите релевантные запросы."}`;table.innerHTML=`<table><thead><tr><th>Выбрать</th><th>Запрос</th><th>Искали</th><th>Видели</th><th>Средняя позиция</th><th>Заказано</th><th>Выручка</th><th>Свежесть</th></tr></thead><tbody>${selection.items.map((item)=>`<tr><td><input type="checkbox" data-query-id="${item.search_query_id}" ${item.selected?"checked":""}></td><td>${esc(item.query_text)}</td><td>${esc(item.searched_users)}</td><td>${esc(item.seen_users)}</td><td>${esc(item.average_position)}</td><td>${esc(item.ordered_units)}</td><td>${esc(item.ordered_revenue_rub)}</td><td>${item.in_latest_period?esc(`${item.evidence_period.period_start} — ${item.evidence_period.period_end}`):`<span class="chip">Нет в свежем периоде</span> ${esc(item.evidence_period.period_start)} — ${esc(item.evidence_period.period_end)}`}</td></tr>`).join("")}</tbody></table>`;button.disabled=false;}
async function saveRelevantQueries(productId){const button=document.querySelector("#relevant-queries-save"),status=document.querySelector("#relevant-queries-status"),previous=competitorState.relevance;button.disabled=true;status.textContent="Сохраняем…";const ids=[...document.querySelectorAll("[data-query-id]:checked")].map((box)=>Number(box.dataset.queryId));try{const selection=await responseBody(await fetch(`/api/products/${productId}/relevant-queries`,{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({search_query_ids:ids})}));competitorState.relevance=selection;renderRelevantQueries(selection);status.textContent=selection.changed?`Сохранено. Выбрано: ${selection.selected_count}.`:`Состав запросов не изменился. Выбрано: ${selection.selected_count}.`;setBenchmarkControls(selection.selected_count>0);if(selection.selected_count>0)await loadCandidates(productId,0);else{competitorState.candidatePage=null;document.querySelector("#benchmark-candidates-list").replaceChildren();document.querySelector("#benchmark-candidates-status").textContent="Сначала сохраните релевантные запросы.";}}catch(error){if(previous)renderRelevantQueries(previous);status.textContent=`${status.textContent} Ошибка: ${error.message}`;button.disabled=false;}}
async function loadBenchmark(productId,requestId=productUiState.workspaceRequestId){try{const benchmark=await responseBody(await fetch(`/api/products/${productId}/benchmark`));if(!isCurrentWorkspaceRequest(requestId,productId))return null;competitorState.benchmark=benchmark;competitorState.selectedProductIds=new Set((benchmark.current_revision?.members||[]).map((item)=>item.product_id));ScozCompetitorState.rememberCandidates(competitorState,benchmark.current_revision?.members);renderSelectedBenchmark();return benchmark;}catch(error){if(!isCurrentWorkspaceRequest(requestId,productId))return null;document.querySelector("#benchmark-save-status").textContent=error.message;return null;}}
async function loadCandidates(productId, offset,requestId=productUiState.workspaceRequestId){const status=document.querySelector("#benchmark-candidates-status");status.textContent="Загрузка кандидатов…";document.querySelector("#benchmark-candidates-prev").disabled=true;document.querySelector("#benchmark-candidates-next").disabled=true;try{const page=await responseBody(await fetch(`/api/products/${productId}/benchmark-candidates?limit=50&offset=${offset}`));if(!isCurrentWorkspaceRequest(requestId,productId))return null;competitorState.candidatePage=page;competitorState.candidateOffset=offset;ScozCompetitorState.rememberCandidates(competitorState,page.items);renderCandidates(page);setBenchmarkControls(true);return page;}catch(error){if(!isCurrentWorkspaceRequest(requestId,productId))return null;status.textContent=error.message;return null;}}
function candidatePhoto(candidate){return candidate.photo_status==="AVAILABLE"&&candidate.photo_url?`<img class="candidate-photo" src="${esc(candidate.photo_url)}" alt="" data-photo-id="${esc(candidate.ozon_product_id)}">`:'<div class="candidate-photo">Фото недоступно</div>';}
function renderCandidates(page){if(!page)return;const status=document.querySelector("#benchmark-candidates-status"),list=document.querySelector("#benchmark-candidates-list");status.textContent=page.readiness==="NO_CANDIDATE_EVIDENCE"?"Нет наблюдений для подбора. Добавьте артикул вручную.":`Найдено кандидатов: ${page.total}`;list.innerHTML=page.items.map((item)=>`<label class="candidate">${candidatePhoto(item)}<span><input type="checkbox" data-candidate-id="${item.product_id}" ${competitorState.selectedProductIds.has(item.product_id)?"checked":""}> <strong>${esc(item.source_title||"Название недоступно")}</strong><br>Ozon ID: ${esc(item.ozon_product_id)} · ${esc(item.seller_name||"Продавец не указан")} · ${esc(item.contextual_price_rub||"Цена не указана")}<br>Лучшая позиция: ${esc(item.best_position??"—")} · запросов: ${esc(item.matched_relevant_query_count??0)} · кластеров: ${esc(item.matched_cluster_count??0)}<br>${esc(item.representative_observed_at||"Наблюдений нет")}</span></label>`).join("");list.querySelectorAll("[data-candidate-id]").forEach((box)=>box.addEventListener("change",()=>{const id=Number(box.dataset.candidateId);if(box.checked)competitorState.selectedProductIds.add(id);else competitorState.selectedProductIds.delete(id);renderSelectedBenchmark();}));list.querySelectorAll("img[data-photo-id]").forEach((image)=>image.addEventListener("error",()=>image.replaceWith(Object.assign(document.createElement("div"),{className:"candidate-photo",textContent:"Фото недоступно"}))));document.querySelector("#benchmark-load-photos").disabled=!credentialState||page.items.length===0;document.querySelector("#benchmark-candidates-prev").disabled=page.offset===0;document.querySelector("#benchmark-candidates-next").disabled=page.offset+page.limit>=page.total;renderSelectedBenchmark();}
async function addManualCandidate(productId){const input=document.querySelector("#manual-ozon-product-id"),button=document.querySelector("#manual-candidate-add"),status=document.querySelector("#benchmark-save-status");button.disabled=true;try{const result=await responseBody(await fetch(`/api/products/${productId}/benchmark-candidates/manual`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({ozon_product_id:input.value})}));competitorState.selectedProductIds.add(result.candidate.product_id);ScozCompetitorState.rememberCandidates(competitorState,[result.candidate]);if(competitorState.candidatePage&&!competitorState.candidatePage.items.some((item)=>item.product_id===result.candidate.product_id))competitorState.candidatePage.items.unshift(result.candidate);input.value="";renderCandidates(competitorState.candidatePage);status.textContent=result.created?"Товар добавлен в локальный каталог и выбран.":"Товар выбран.";}catch(error){status.textContent=error.message;}finally{button.disabled=!(competitorState.relevance?.selected_count>0);}}
function renderSelectedBenchmark(){const revision=competitorState.benchmark?.current_revision;document.querySelector("#benchmark-revision").textContent=revision?`Текущая ревизия ${revision.revision}`:"Ещё не сохранено";ScozCompetitorState.rememberCandidates(competitorState,[...(competitorState.candidatePage?.items||[]),...(revision?.members||[])]);const byId=competitorState.metadataByProductId;document.querySelector("#benchmark-selected-list").innerHTML=competitorState.selectedProductIds.size?[...competitorState.selectedProductIds].map((id)=>{const item=byId.get(id)||{};return `<div>Ozon ID: ${esc(item.ozon_product_id||id)} <button type="button" class="button button-ghost button-compact" data-remove-member="${id}">Удалить</button></div>`;}).join(""):"Выберите хотя бы одного конкурента.";document.querySelectorAll("[data-remove-member]").forEach((button)=>button.addEventListener("click",()=>{competitorState.selectedProductIds.delete(Number(button.dataset.removeMember));renderSelectedBenchmark();renderCandidates(competitorState.candidatePage);}));}
async function saveBenchmark(productId){const button=document.querySelector("#benchmark-save"),status=document.querySelector("#benchmark-save-status");if(!competitorState.selectedProductIds.size){status.textContent="Выберите хотя бы одного конкурента.";return;}button.disabled=true;status.textContent="Сохраняем…";try{const result=await responseBody(await fetch(`/api/products/${productId}/benchmark/revisions`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({member_product_ids:[...competitorState.selectedProductIds]})}));competitorState.benchmark={benchmark_set:result.benchmark_set,current_revision:result.revision};renderSelectedBenchmark();status.textContent=result.result==="NO_CHANGE"?`Состав не изменился — ревизия ${result.revision.revision}`:result.result==="CREATED"?`Создана ревизия ${result.revision.revision}`:`Состав обновлён — ревизия ${result.revision.revision}`;competitorState.coreBenchmark=null;if(document.querySelector("#core-benchmark-panel")?.hidden===false)await openCoreBenchmark();}catch(error){status.textContent=error.message;}finally{button.disabled=!(competitorState.relevance?.selected_count>0);}}

function rememberManualToken(){const value=document.querySelector("#mpstats-token").value;if(!value)throw new Error("Введите токен MPStats.");credentialState={mpstats:{token:value}};document.querySelector("#benchmark-load-photos").disabled=!(competitorState.candidatePage?.items.length);return value;}
async function testMpstatsSource(){const button=document.querySelector("#mpstats-test"),status=document.querySelector("#mpstats-status"),probe=document.querySelector("#mpstats-probe-sku").value;button.disabled=true;status.setAttribute("aria-busy","true");status.textContent="Проверяем подключение…";try{const token=rememberManualToken();
const result=await responseBody(await fetch("/api/sources/mpstats/test",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({token:token,ozon_product_id:probe})}));status.textContent=result.message;}catch(error){status.textContent=error.message;}finally{button.disabled=false;status.setAttribute("aria-busy","false");}}
async function loadMpstatsPhotos(){const button=document.querySelector("#benchmark-load-photos"),status=document.querySelector("#benchmark-candidates-status"),page=competitorState.candidatePage;if(!credentialState||!page)return;button.disabled=true;status.textContent="Загружаем фото…";try{const ids=page.items.map((item)=>item.ozon_product_id);const result=await responseBody(await fetch("/api/sources/mpstats/ozon-product-previews",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({token:credentialState.mpstats.token,ozon_product_ids:ids})}));const previews=new Map(result.items.map((item)=>[item.ozon_product_id,item]));page.items.forEach((item)=>{const preview=previews.get(item.ozon_product_id);if(preview){item.photo_status=preview.photo_status;item.photo_url=preview.photo_url;}});renderCandidates(page);status.textContent="Фото обновлены.";}catch(error){status.textContent=error.message;}finally{button.disabled=!credentialState||!page.items.length;}}
async function saveMpstatsKeystore(){const status=document.querySelector("#mpstats-status"),passwordInput=document.querySelector("#mpstats-save-password"),confirmationInput=document.querySelector("#mpstats-save-password-confirm"),password=passwordInput.value,confirmation=confirmationInput.value;if(!credentialState){status.textContent="Сначала введите и проверьте токен MPStats.";return;}if(!password||password!==confirmation){status.textContent="Пароли не совпадают или не заполнены.";return;}const button=document.querySelector("#mpstats-save-keystore");button.disabled=true;try{const envelope=await ScozKeystore.encryptMpstatsCredentials({token:credentialState.mpstats.token},password);ScozKeystore.downloadEnvelope(envelope);passwordInput.value="";confirmationInput.value="";status.textContent="Зашифрованный файл сохранён.";}catch{status.textContent="Не удалось сохранить зашифрованный файл.";}finally{button.disabled=false;}}
async function openMpstatsKeystore(){const fileInput=document.querySelector("#mpstats-keystore-file"),openPassword=document.querySelector("#mpstats-open-password"),status=document.querySelector("#mpstats-status"),button=document.querySelector("#mpstats-open-keystore");const previousState=credentialState;button.disabled=true;try{if(!fileInput.files[0])throw new Error("Выберите файл ключей.");const envelope=ScozKeystore.parseEnvelope(await fileInput.files[0].text());const credentials=await ScozKeystore.decryptMpstatsCredentials(envelope,openPassword.value);credentialState={mpstats:{token:credentials.token}};document.querySelector("#mpstats-token").value="";fileInput.value="";status.textContent="Ключи MPStats открыты в текущей вкладке.";if(competitorState.candidatePage)renderCandidates(competitorState.candidatePage);}catch(error){credentialState=previousState;status.textContent=error.code==="KEYSTORE_DECRYPT_FAILED"?"Не удалось открыть файл: неверный пароль или файл повреждён.":"Не удалось открыть файл ключей.";}finally{openPassword.value="";button.disabled=false;}}
function lockCredentials(){credentialState=null;for(const id of ["mpstats-token","mpstats-save-password","mpstats-save-password-confirm","mpstats-keystore-file","mpstats-open-password"])document.querySelector(`#${id}`).value="";document.querySelector("#mpstats-status").textContent="Ключи заблокированы.";if(competitorState.candidatePage){competitorState.candidatePage.items.forEach((item)=>{item.photo_url=null;item.photo_status="NOT_REQUESTED";});renderCandidates(competitorState.candidatePage);}document.querySelector("#benchmark-load-photos").disabled=true;}
