function updateFilenameGuidance(sourceKey,file){const source=importSources[sourceKey],definition=ScozImportUi.sources[sourceKey],guidance=document.querySelector(source.guidance),status=document.querySelector(source.status);guidance.classList.remove("is-match","is-warning");setStatusState(status,"neutral");status.textContent=file?"Файл готов к импорту.":"Выберите XLSX-файл";if(!file){guidance.textContent="Выберите выгрузку с указанным именем.";return;}const classification=ScozImportUi.classifyFilename(sourceKey,file.name);if(classification.kind==="MATCH"){guidance.classList.add("is-match");guidance.textContent=`Файл похож на нужный тип: ${definition.pattern}`;}else if(classification.kind==="KNOWN_OTHER"){const detected=ScozImportUi.sources[classification.detectedSource];guidance.classList.add("is-warning");guidance.textContent=`Похоже, выбран отчёт «${detected.label}» (${detected.pattern}). Для этой карточки нужен ${definition.pattern}. Можно продолжить: тип будет проверен по содержимому.`;}else{guidance.classList.add("is-warning");guidance.textContent="Имя файла не похоже на стандартное имя выгрузки Ozon. Можно продолжить — тип отчёта будет проверен по содержимому.";}}
const bindImport=(sourceKey,nameSelector,submitter)=>{const source=importSources[sourceKey],input=document.querySelector(source.input),button=document.querySelector(source.button);input.addEventListener("change",()=>{const file=input.files[0];document.querySelector(nameSelector).textContent=file?.name||"Файл не выбран";button.disabled=!file||Boolean(activeImport);updateFilenameGuidance(sourceKey,file);});button.addEventListener("click",()=>{if(activeImport)return;if(input.files[0])submitter(input.files[0]);});};
